#!/usr/bin/env bash
is_even() {
    (( $1 % 2 == 0 ))
}
square() {
    echo $(( $1 * $1 ))
}
for n in 3 4; do
    if is_even "$n"; then echo "$n is even"; else echo "$n is odd"; fi
done
area=$(square 6)
echo "area is $area"

